p='packs/basics/test/declared-check-spec-keys.test.mjs'
s=open(p).read()
old = """      {
        id: 'fx-neighbour', severity: 'advisory', failureMessage: 'the rule beside it',
        scanFiles: '/\\\\.txt$/',
        matchLines: [{ match: '/OTHER/', what: 'saw the other', fix: 'remove it' }],
      },
    ], null, 2),
  } });"""
new = """      {
        id: 'fx-neighbour', severity: 'advisory', failureMessage: 'the rule beside it',
        scanFiles: '/\\\\.txt$/',
        matchLines: [{ match: '/OTHER/', what: 'saw the other', fix: 'remove it' }],
      },
    ], null, 2),
    'a.txt': 'TOK\\nOTHER\\n',
  } });"""
assert old in s
s = s.replace(old, new)
old2 = s[s.index('    assert.deepEqual(rules[0].run(ctx)'):s.index('  } finally { cleanup(root); }\n});\n', s.index('    assert.deepEqual(rules[0].run(ctx)'))]
new2 = """    assert.deepEqual(rules[0].run(ctx).map((f) => f.what), ['saw it']);
    assert.deepEqual(rules[1].run(ctx).map((f) => f.what), ['saw the other']);
    const findings = run(root);
    assert.equal(findings.length, 1);
    assert.match(findings[0].what, /"fx-future-key" carries "sinceRelease", which is not a spec key/);
"""
s = s.replace(old2, new2)
open(p,'w').write(s)
EOF
node --test packs/basics/test/declared-check-spec-keys.test.mjs 2>&1 | tail -20

